console.log("Production SHA:", health.seniorDeveloperRuntime?.commitSha?.slice(0, 12));
console.log("Production status:", health.status);
console.log("Production bootTime:", health.bootTime);

// Check GitHub HEAD
const headRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ action: "github_get_repo_head", confirm: true, confirmText: "", input: { branch: "main" } }),
});
const headData = await headRes.json();
console.log("GitHub HEAD:", headData.result?.headSha?.slice(0, 12));
console.log("GitHub message:", headData.result?.headCommitMessage?.slice(0, 80));
