cd /home/user/rork-app

# Check CI status - list all recent workflow runs
bun -e '
const fs = require("fs");
const token = fs.readFileSync("/tmp/owner_token.txt", "utf-8").trim();

// List workflow runs
const res = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ action: "github_list_workflow_runs", confirm: true, confirmText: "", input: { per_page: 10 } }),
});
const data = await res.json();
if (data.result?.runs) {
  console.log("=== CI RUNS (latest 10) ===");
  for (const run of data.result.runs) {
    console.log("run:", run.id, 
      "| workflow:", run.name?.replace(".github/workflows/", ""),
      "| sha:", (run.headSha || "").slice(0, 7),
      "| conclusion:", run.conclusion,
      "| status:", run.status,
      "| created:", run.createdAt,
      "| updated:", run.updatedAt);
  }
} else {
  console.log("Failed to list runs:", JSON.stringify(data).slice(0, 300));
}

// Try to read the CI workflow file to understand what jobs it should have
const wfRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ action: "github_read_file", confirm: true, confirmText: "", input: { path: ".github/workflows/ivx-ci.yml" } }),
});
const wfData = await wfRes.json();
if (wfData.result?.content) {
  const content = Buffer.from(wfData.result.content, "base64").toString("utf-8");
  // Extract job names
  const jobMatches = content.match(/^\s{2}(\w+):\s*$/gm);
  console.log("\\n=== CI WORKFLOW JOBS ===");
  if (jobMatches) {
    for (const m of jobMatches) {
      const name = m.trim().replace(":","");
      if (["name","on","jobs","env","permissions","concurrency"].includes(name)) continue;
      console.log("  job:", name);
    }
  }
  // Check if there is a billing or minutes issue
  console.log("\\n=== WORKFLOW FIRST 30 LINES ===");
  console.log(content.split("\\n").slice(0, 30).join("\\n"));
} else {
  console.log("Failed to read workflow:", JSON.stringify(wfData).slice(0, 300));
}
' 2>&1

