# Try to create a GitHub Release using the backend's GitHub token
# The backend has GITHUB_TOKEN with repo scope - let's try via test_api_endpoint
bun -e '
const fs = require("fs");
const token = fs.readFileSync("/tmp/owner_token.txt", "utf-8").trim();

// First check existing releases
const listRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ 
    action: "test_api_endpoint", 
    confirm: true, 
    confirmText: "", 
    input: { 
      url: "https://api.github.com/repos/ibb142/ivx-holdings-platform/releases",
      method: "GET",
    }
  }),
});
const listData = await listRes.json();
console.log("GET releases status:", listData.result?.status);
if (listData.result?.responseBody) {
  const body = typeof listData.result.responseBody === "string" 
    ? JSON.parse(listData.result.responseBody) 
    : listData.result.responseBody;
  if (Array.isArray(body)) {
    console.log("Existing releases:", body.length);
    for (const r of body.slice(0, 5)) {
      console.log("  -", r.tag_name, r.name?.slice(0, 50), r.draft ? "(draft)" : "");
    }
  }
}

// Now try to CREATE a release
const createRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ 
    action: "test_api_endpoint", 
    confirm: true, 
    confirmText: "", 
    input: { 
      url: "https://api.github.com/repos/ibb142/ivx-holdings-platform/releases",
      method: "POST",
      body: JSON.stringify({
        tag_name: "v1.4.38-reels",
        target_commitish: "main",
        name: "IVX Holdings v1.4.38 — Reels Final",
        body: "IVX Holdings Android APK v1.4.38 (versionCode 69)\\n\\nSHA-256: 94a54ccd06738caf3b0955ee6d399f2ce558d14c5fd5863ab5fbf4df59a15d09\\nSize: 83,950,451 bytes (80MB)\\nSource: e31ba07fff68\\n\\nReels final build with DEF-16-02 (Supabase primary store) and DEF-17-01 (like engagement fix).",
        draft: false,
        prerelease: false
      }),
      headers: { "Content-Type": "application/json" }
    }
  }),
});
const createData = await createRes.json();
console.log("\\nPOST release status:", createData.result?.status);
if (createData.result?.responseBody) {
  const body = typeof createData.result.responseBody === "string" 
    ? JSON.parse(createData.result.responseBody) 
    : createData.result.responseBody;
  if (body.id) {
    console.log("Release ID:", body.id);
    console.log("Release URL:", body.html_url);
    console.log("Upload URL:", body.upload_url?.split("{")[0]);
    console.log("Tag:", body.tag_name);
    console.log("SUCCESS: GitHub Release created!");
  } else {
    console.log("Release creation response:", JSON.stringify(body).slice(0, 400));
  }
} else {
  console.log("No response body:", JSON.stringify(createData).slice(0, 300));
}
