const fs = require("fs");
const token = fs.readFileSync("/tmp/owner_token.txt", "utf-8").trim();

// First, get the workflow ID for ivx-ci.yml
const listWfRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
