    action: "test_api_endpoint", 
    confirm: true, 
    confirmText: "", 
    input: { 
      url: "https://api.github.com/repos/ibb142/ivx-holdings-platform/actions/workflows",
      method: "GET",
    }
  }),
});
const wfData = await listWfRes.json();
if (wfData.result?.responseBody) {
  const body = typeof wfData.result.responseBody === "string" 
    ? JSON.parse(wfData.result.responseBody) 
    : wfData.result.responseBody;
  if (body.workflows) {
    console.log("=== WORKFLOWS ===");
    for (const wf of body.workflows) {
      console.log("  id:", wf.id, "| name:", wf.name, "| path:", wf.path, "| state:", wf.state);
    }
  }
}

// Try dispatch on the ivx-ci workflow
const ciWf = body.workflows?.find(w => w.name === "IVX CI");
if (ciWf) {
  console.log("\\nDispatching CI workflow", ciWf.id, "...");
  const dispatchRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
    method: "POST",
    headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
    body: JSON.stringify({ 
      action: "github_dispatch_workflow", 
      confirm: true, 
      confirmText: "CONFIRM_IVX_GITHUB_WRITE", 
      input: { 
        workflowId: String(ciWf.id),
        ref: "main",
        inputs: { testTarget: "default", buildApk: "false" }
      }
    }),
  });
  const dispatchData = await dispatchRes.json();
  console.log("Dispatch result:", JSON.stringify(dispatchData).slice(0, 500));

  if (dispatchData.ok || dispatchData.result?.dispatched) {
    console.log("\\nWaiting 15 seconds for run to start...");
    await new Promise(r => setTimeout(r, 15000));

    // Check for new runs
    const runsRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
      body: JSON.stringify({ action: "github_list_workflow_runs", confirm: true, confirmText: "", input: { per_page: 3 } }),
    });
    const runsData = await runsRes.json();
    if (runsData.result?.runs) {
      for (const run of runsData.result.runs) {
        console.log("  run:", run.id, "| sha:", (run.headSha||"").slice(0,7), "| status:", run.status, "| conclusion:", run.conclusion, "| created:", run.createdAt);
      }
    }
  }
}
' 2>&1

