const rb = createData.result?.responseBody;
if (rb) {
  // Handle both string and object
  let body;
  if (typeof rb === "string") {
    try { body = JSON.parse(rb); } catch(e) { console.log("Raw response (first 500 chars):", rb.slice(0, 500)); body = null; }
  } else {
    body = rb;
  }
  if (body) {
    if (body.id) {
      console.log("Release ID:", body.id);
      console.log("Release URL:", body.html_url);
      console.log("Upload URL:", body.upload_url?.split("{")[0]);
      console.log("Tag:", body.tag_name);
      console.log("Draft:", body.draft);
      fs.writeFileSync("/tmp/release_info.json", JSON.stringify({ id: body.id, uploadUrl: body.upload_url?.split("{")[0], htmlUrl: body.html_url, tag: body.tag_name }));
      console.log("SUCCESS: GitHub Release created!");
    } else {
      console.log("Error response:", JSON.stringify(body).slice(0, 400));
    }
  }
} else {
  console.log("No response body. Full result:", JSON.stringify(createData).slice(0, 500));
}
