# ITEM 2: Create GitHub Release using RORK_PUBLIC_GITHUB_TOKEN via bun (avoids shell substitution issues)
bun -e '
const token = process.env.RORK_PUBLIC_GITHUB_TOKEN;
if (!token) { console.log("NO RORK_PUBLIC_GITHUB_TOKEN"); process.exit(1); }
console.log("Token prefix:", token.slice(0, 10) + "..." + token.slice(-4));
console.log("Token length:", token.length);

// Verify token access
const repoRes = await fetch("https://api.github.com/repos/ibb142/ivx-holdings-platform", {
  headers: { Authorization: "token " + token, Accept: "application/vnd.github+json" }
});
const repoData = await repoRes.json();
console.log("Repo:", repoData.full_name, "| private:", repoData.private, "| perms:", JSON.stringify(repoData.permissions));

// Check X-OAuth-Scopes header
const scopesHeader = repoRes.headers.get("x-oauth-scopes");
console.log("Scopes:", scopesHeader);

if (!repoData.permissions?.push) {
  console.log("ERROR: Token does not have push permission to this repo");
  process.exit(1);
}

// Create a draft release
console.log("\\nCreating GitHub Release...");
const createRes = await fetch("https://api.github.com/repos/ibb142/ivx-holdings-platform/releases", {
  method: "POST",
  headers: {
    Authorization: "token " + token,
    Accept: "application/vnd.github+json",
    "Content-Type": "application/json"
  },
  body: JSON.stringify({
    tag_name: "v1.4.38-reels-final",
    target_commitish: "main",
    name: "IVX Holdings v1.4.38 — Reels Final",
    body: "IVX Holdings Android APK v1.4.38 (versionCode 69)\\n\\nSHA-256: 94a54ccd06738caf3b0955ee6d399f2ce558d14c5fd5863ab5fbf4df59a15d09\\nSize: 83,950,451 bytes (80MB)\\nSource commit: e31ba07fff68\\n\\nIncludes:\\n- DEF-16-02: Supabase as primary read/write for video platform store (persistence verified across restart)\\n- DEF-17-01: Like engagement field fix (guest_id path)\\n- Full transcoding pipeline (HLS 1080p/720p/480p/360p)\\n- 1011 passing tests",
    draft: true,
    prerelease: false
  })
});
const createData = await createRes.json();
console.log("Release creation HTTP status:", createRes.status);
if (createData.id) {
  console.log("Release ID:", createData.id);
  console.log("Release URL:", createData.html_url);
  console.log("Upload URL:", createData.upload_url?.split("{")[0]);
  console.log("Tag:", createData.tag_name);

  // Save release info for asset upload
  const fs = require("fs");
  fs.writeFileSync("/tmp/release_info.json", JSON.stringify({
    id: createData.id,
    uploadUrl: createData.upload_url?.split("{")[0],
    htmlUrl: createData.html_url,
    tag: createData.tag_name
  }));
  console.log("\\nSUCCESS: GitHub Release created!");
} else {
  console.log("FAILED:", JSON.stringify(createData).slice(0, 500));
}
' 2>&1

