  console.log("First video:", videos[0].id, "| title:", videos[0].title, "| featured:", videos[0].is_featured, "| order:", videos[0].display_order, "| status:", videos[0].status);
}

const testVid = videos[0];
if (!testVid) {
  console.log("No videos found for admin QA");
  process.exit(0);
}

