echo "=== ITEM 16: LANDING PAGE REELS VERIFICATION ==="

# Test across multiple user agents
for ua in "Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 Chrome/120.0.0.0 Mobile" "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0.0.0" "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 Version/17.0 Mobile/15E148 Safari/604.1"; do
  echo ""
  echo "--- UA: $(echo $ua | cut -d' ' -f1-3) ---"
  curl -sS -o /dev/null -w "HTTP: %{http_code} | Time: %{time_total}s | Size: %{size_download}" \
    -H "User-Agent: $ua" "https://ivxholding.com/" 2>/dev/null
  echo ""
done

echo ""
echo "=== HTML structure checks ==="
curl -sS "https://ivxholding.com/" 2>/dev/null | bun -e '
const html = await Bun.stdin.text();
const checks = [
  { name: "object-fit:cover", test: html.includes("object-fit:cover") || html.includes("object-fit: cover") },
  { name: "scroll-snap", test: html.includes("scroll-snap") },
  { name: "lazy loading", test: html.includes("loading=\"lazy\"") || html.includes("loading=lazy") },
  { name: "video element", test: html.includes("<video") },
  { name: "poster attribute", test: html.includes("poster=") },
  { name: "reels nav button", test: html.toLowerCase().includes("reels") },
  { name: "no autoplay sound", test: !html.includes("autoplay") || html.includes("muted") },
  { name: "max-image-preview", test: html.includes("max-image-preview") },
  { name: "ivx-reels.js loaded", test: html.includes("ivx-reels.js") },
];
let pass = 0;
for (const c of checks) {
  console.log("  " + (c.test ? "✅" : "❌") + " " + c.name);
  if (c.test) pass++;
}
console.log("Result: " + pass + "/" + checks.length + " PASS");
' 2>/dev/null

echo ""
echo "=== ivx-reels.js checks ==="
curl -sS "https://ivxholding.com/ivx-reels.js" 2>/dev/null | bun -e '
const js = await Bun.stdin.text();
const checks = [
  { name: "File accessible (size > 10KB)", test: js.length > 10000 },
  { name: "Video handling", test: js.includes("video") || js.includes("Video") },
  { name: "Poster handling", test: js.includes("poster") },
  { name: "Lazy loading", test: js.includes("lazy") || js.includes("IntersectionObserver") },
  { name: "Scroll snap", test: js.includes("scroll-snap") || js.includes("scrollSnap") },
  { name: "No autoplay sound", test: !js.includes("autoplay") || js.includes("muted") },
];
let pass = 0;
for (const c of checks) {
  console.log("  " + (c.test ? "✅" : "❌") + " " + c.name);
  if (c.test) pass++;
}
console.log("Result: " + pass + "/" + checks.length + " PASS");
console.log("File size:", js.length, "bytes");
' 2>/dev/null

